fn solve(input: Vec<char>) -> Vec<char> {
    // Mapping from digit to its "good count"
    let good_counts = [
        2, // '0'
        7, // '1'
        2, // '2'
        3, // '3'
        3, // '4'
        4, // '5'
        2, // '6'
        5, // '7'
        1, // '8'
        2, // '9'
    ];
    
    // Get the first two characters as ASCII digits
    let first_digit = input[0] as u8 - b'0';
    let second_digit = input[1] as u8 - b'0';
    
    // Compute the product of good counts
    let product = good_counts[first_digit as usize] * good_counts[second_digit as usize];
    
    // Convert product to string and add newline
    let mut result = product.to_string();
    result.push('\n');
    
    // Convert to Vec<char>
    result.chars().collect()
}